def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 140:
                rich_count += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))
                status = prev.get('status')
                hp_after = prev.get('hp_after')
                if status == 'lost' or (hp_after is not None and hp_after <= 3):
                    desperate_count += 1

    if budget <= 0:
        return 0

    if not alive:
        return min(budget, 18)

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0

    supply_pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_pressure < 0:
        supply_pressure = 0
    if supply_pressure > 1:
        supply_pressure = 1

    survival_urgent = hp <= 2 or no_water_days >= 2
    caution = hp <= 4 or no_water_days >= 1

    if survival_urgent:
        bid = max(0.92 * DAILY_SALARY, highest_prev + 4)
        if supply <= 17:
            bid += 10
        return min(budget, bid)

    if caution:
        bid = max(0.72 * DAILY_SALARY, avg_prev * 0.9 + 3)
        if desperate_count >= 2:
            bid += 8
        if supply <= 17:
            bid += 6
        return min(budget, bid)

    base = 0.34 * DAILY_SALARY
    bid = base + 18 * supply_pressure

    if highest_prev >= 150:
        bid = min(bid, 0.42 * DAILY_SALARY)
    elif highest_prev >= 120:
        bid = min(bid + 2, 0.48 * DAILY_SALARY)
    else:
        bid = max(bid, avg_prev * 0.55 + 1)

    if desperate_count >= 2:
        bid += 5
    if rich_count >= 3 and supply <= 18:
        bid += 6

    if day >= 8 and hp >= 6:
        bid *= 0.9

    if budget < 90:
        bid = min(bid, 0.55 * DAILY_SALARY)

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate competition pressure
    pressure = 0.0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / float(len(yesterday_bids))
        # Cindy-type behavior: very high bids imply aggressive securing
        if highest_prev_bid >= DAILY_SALARY * 1.3:
            pressure = 0.85
        elif avg_prev_bid >= DAILY_SALARY:
            pressure = 0.65
        else:
            pressure = 0.45

    # If we are low HP or have gone multiple days without water, overbid more
    urgency = 0.0
    if my_hp <= 2.0:
        urgency = 0.95
    elif my_hp <= 4.0:
        urgency = 0.75
    elif my_no_water_days >= 2:
        urgency = 0.6
    else:
        urgency = 0.45

    # Supply level: lower supply increases chance of being priced out
    # supply is between 15 and 25; normalize to [0,1]
    supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    # When supply is low (norm near 0), increase bid
    supply_factor = 1.0 + (0.25 * (1.0 - supply_norm))

    # Base target bid: moderate fraction of daily salary, adjusted by pressure/urgency and supply
    target = DAILY_SALARY * (0.5 + 0.25 * pressure + 0.25 * urgency)
    target *= supply_factor

    # If yesterday had very high highest bid, slightly shadow it without fully matching
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 1.3:
            target = max(target, DAILY_SALARY * 0.9)
        elif highest_prev_bid >= DAILY_SALARY:
            target = max(target, DAILY_SALARY * 0.7)
        # Avoid runaway: cap relative to highest_prev_bid
        target = min(target, highest_prev_bid * 0.85)

    # Ensure we can pay and still bid non-negative
    bid = max(0.0, min(my_budget, target))

    # If budget is extremely low, bid whatever we can but avoid zero if urgency is high
    if my_budget <= DAILY_SALARY * 0.15:
        if urgency >= 0.75 and my_hp <= 4.0:
            bid = max(0.0, min(my_budget, DAILY_SALARY * 0.25))
        else:
            bid = max(0.0, min(my_budget, DAILY_SALARY * 0.1))

    return float(bid)

